import { marksInOrder } from './marks-in-order';
import { nodesInOrder } from './nodes-in-order';
export function getNodesAndMarksMap() {
  const nodes = nodesInOrder.reduce((acc, {
    name,
    spec
  }) => {
    acc[name] = spec;
    return acc;
  }, {});
  const marks = marksInOrder.reduce((acc, {
    name,
    spec
  }) => {
    acc[name] = spec;
    return acc;
  }, {});
  return {
    nodes,
    marks
  };
}